PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS challenges (id TEXT PRIMARY KEY, address TEXT NOT NULL, role TEXT NOT NULL, payload TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, address TEXT NOT NULL, role TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, window INTEGER NOT NULL, count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS drafts (kind TEXT NOT NULL, id TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(kind,id));
CREATE TABLE IF NOT EXISTS files (listing_id TEXT PRIMARY KEY, object_key TEXT NOT NULL UNIQUE, name TEXT NOT NULL, content_type TEXT NOT NULL, size INTEGER NOT NULL, hash TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS uploads (token TEXT PRIMARY KEY, listing_id TEXT NOT NULL, object_key TEXT NOT NULL, upload_id TEXT NOT NULL, name TEXT NOT NULL, content_type TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS downloads (buyer TEXT NOT NULL, listing_id TEXT NOT NULL, started INTEGER NOT NULL, PRIMARY KEY(buyer,listing_id));
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY, level INTEGER NOT NULL, tag TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync (id INTEGER PRIMARY KEY CHECK(id=1), cursor INTEGER NOT NULL DEFAULT 0, level INTEGER NOT NULL DEFAULT 0, block_hash TEXT, updated TEXT);
INSERT OR IGNORE INTO sync(id) VALUES(1);
CREATE TABLE IF NOT EXISTS operations (hash TEXT PRIMARY KEY, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS locks (id TEXT PRIMARY KEY, owner TEXT NOT NULL, expires INTEGER NOT NULL);
